-- 044: реакции на зачитанные показания (вкладка «Зачитать показания»).
-- Сверка: кто по канону должен отреагировать на чужие показания, но отвечал общей заглушкой.
-- Все реакции резервные (fallback, без grants): граф и доступность улик не меняются.
-- Повторный запуск безопасен: сначала удаляются реакции с теми же id.
begin;
update characters set reaction_rules = (select coalesce(jsonb_agg(r), '[]'::jsonb) from jsonb_array_elements(coalesce(reaction_rules, '[]'::jsonb)) r where r->>'id' not in ('R301','R302','R311','R321')) || '[{"id": "R301", "on": "c4c95f03-86b0-5820-b9f4-736453e2dbef", "requires": [], "text": "Ерлан затягивается. Долго выпускает дым.\n— Ну ездил. Я на воротах стою, братан, я всех знаю, кто во сколько. Работа такая.\n(стряхивает пепел мимо пепельницы)\n— Кому говорил? Никому не говорил. Кому оно надо.", "grants": [], "fallback": true}, {"id": "R302", "on": "c4c95f03-86b0-5820-b9f4-736453e2dbef", "requires": ["b229ab87-5e5b-5f61-8a7b-18c17718e4cf"], "text": "— Четверги, да. — Ерлан смотрит в стол. — С этого всё и началось. Я ж думал: поговорят по-мужски, и всё.", "grants": [], "fallback": true}, {"id": "R311", "on": "b170d031-ba6c-5e70-829f-cbd96f761931", "requires": [], "text": "Ерлан перестаёт качать ногой.\n— Похитили?.. — Долго молчит. Сигарета догорает до фильтра. — Я тут при чём, братан. Я на воротах стою. Про выкуп первый раз слышу.", "grants": [], "fallback": true}, {"id": "R321", "on": "0146fe89-1029-5d65-87bb-f750dfe7ad2d", "requires": [], "text": "— Пацан этот? — Ерлан пожимает плечами. — Не знаю такого. Фархад мне про него ничего не говорил. Про пацанов разговора не было.", "grants": [], "fallback": true}]'::jsonb where id = '2d9e7245-2e05-5079-86f1-f9b2edb1f3e9';  -- Ерлан Нуртазин
update characters set reaction_rules = (select coalesce(jsonb_agg(r), '[]'::jsonb) from jsonb_array_elements(coalesce(reaction_rules, '[]'::jsonb)) r where r->>'id' not in ('R303','R320','R322')) || '[{"id": "R303", "on": "c4c95f03-86b0-5820-b9f4-736453e2dbef", "requires": [], "text": "Данияр поправляет очки.\n— Это не секрет. В четверг в пять он уезжал. Совещания на четверг вечером мы не ставили.\n(пауза)\n— Знали все: офис, склад, охрана на КПП.", "grants": [], "fallback": true}, {"id": "R320", "on": "0146fe89-1029-5d65-87bb-f750dfe7ad2d", "requires": [], "text": "Данияр снимает очки, протирает.\n— Высокий, в ушанке. На остановке. — Кивает сам себе. — Да. Мальчишка совсем. Я думал, старше.", "grants": [], "fallback": true}, {"id": "R322", "on": "b229ab87-5e5b-5f61-8a7b-18c17718e4cf", "requires": [], "text": "Данияр долго смотрит на лист.\n— Ерлан. Охрана от агентства, бывший милиционер. Мы думали — надёжно.\n(надевает очки)\n— За старый долг. Полторы тысячи. Дешёво.", "grants": [], "fallback": true}]'::jsonb where id = 'a7955352-673d-5ff7-bfcc-506079544d1f';  -- Данияр Ахметов
update characters set reaction_rules = (select coalesce(jsonb_agg(r), '[]'::jsonb) from jsonb_array_elements(coalesce(reaction_rules, '[]'::jsonb)) r where r->>'id' not in ('R305')) || '[{"id": "R305", "on": "c4c95f03-86b0-5820-b9f4-736453e2dbef", "requires": [], "text": "Алия поднимает брови.\n— Один, по четвергам? Не знала. — Коротко пожимает плечами. — Мы после развода не разговариваем. При мне он по четвергам дома сидел.", "grants": [], "fallback": true}]'::jsonb where id = '96e916c8-7fd0-5edc-a4fe-1a6aeda231bf';  -- Алия Сартакова (Жумабаева)
update characters set reaction_rules = (select coalesce(jsonb_agg(r), '[]'::jsonb) from jsonb_array_elements(coalesce(reaction_rules, '[]'::jsonb)) r where r->>'id' not in ('R308')) || '[{"id": "R308", "on": "42ea83ef-f3ad-504f-99e0-da4ecb9fe57d", "requires": [], "text": "Виктор перестаёт мять кепку.\n— В пятницу пустой? — Пауза. — А в воскресенье я приехал — машина стоит. Ворота закрыты.\n— Это что ж, её потом кто-то пригнал?", "grants": [], "fallback": true}]'::jsonb where id = '54b23338-3cf2-5d0a-99c4-91c0de226522';  -- Виктор Гринько
update characters set reaction_rules = (select coalesce(jsonb_agg(r), '[]'::jsonb) from jsonb_array_elements(coalesce(reaction_rules, '[]'::jsonb)) r where r->>'id' not in ('R304','R309','R318')) || '[{"id": "R304", "on": "c4c95f03-86b0-5820-b9f4-736453e2dbef", "requires": [], "text": "— По четвергам он отдыхал. На даче. Один. — Валентина Петровна поправляет скатерть. — После развода ему нужно было где-то молчать. Я не спрашивала.", "grants": [], "fallback": true}, {"id": "R309", "on": "42ea83ef-f3ad-504f-99e0-da4ecb9fe57d", "requires": [], "text": "— Алия ездила на дачу? — Валентина Петровна сжимает губы. — За бумагами, конечно. Она всегда знает, когда что забрать.\n(пауза)\n— Простите. Это к делу не относится.", "grants": [], "fallback": true}, {"id": "R318", "on": "009a36f7-b362-586d-8943-61cd46149c3c", "requires": [], "text": "Валентина Петровна снимает очки.\n— Фархад сидел за их общую фирму. Игорь об этом не любил говорить. Я думала, они это пережили.\n(пауза)\n— «Садиться не просил»… Это Игорь мог. Когда злился, он всегда находил самое больное слово.", "grants": [], "fallback": true}]'::jsonb where id = '0e8eb7cc-a947-5525-80eb-0978454d919b';  -- Валентина Петровна Сартакова
update characters set reaction_rules = (select coalesce(jsonb_agg(r), '[]'::jsonb) from jsonb_array_elements(coalesce(reaction_rules, '[]'::jsonb)) r where r->>'id' not in ('R306','R307','R312','R313','R313b','R314','R315','R316','R317','R319','R323')) || '[{"id": "R306", "on": "c4c95f03-86b0-5820-b9f4-736453e2dbef", "requires": [], "text": "Олжас смотрит в пол.\n— Мен не знаю, кто куда ездит. Я на базаре работаю. Грузчик.", "grants": [], "fallback": true}, {"id": "R307", "on": "c4c95f03-86b0-5820-b9f4-736453e2dbef", "requires": ["3ad29f0f-a1d4-5f8d-abca-4dd530eabf4c"], "text": "— Аке сказал: в четверг он один поедет. Без водителя. — Олжас трёт ладони о колени. — Откуда знал — не сказал. Я не спрашивал.", "grants": [], "fallback": true}, {"id": "R312", "on": "b170d031-ba6c-5e70-829f-cbd96f761931", "requires": [], "text": "Олжас слушает. На словах «звонили из таксофона» сжимает колени.\n— Мен не звонил. Какие деньги. — Не поднимает глаз. — У меня телефона нет даже.", "grants": [], "fallback": true}, {"id": "R313", "on": "b170d031-ba6c-5e70-829f-cbd96f761931", "requires": ["0146fe89-1029-5d65-87bb-f750dfe7ad2d"], "text": "— Это я звонил. — Олжас говорит в пол. — Из автомата. А в субботу — из дома, у немцев. Автомат на остановке сломан был.", "grants": [], "fallback": true}, {"id": "R313b", "on": "b170d031-ba6c-5e70-829f-cbd96f761931", "requires": ["0146fe89-1029-5d65-87bb-f750dfe7ad2d", "3ad29f0f-a1d4-5f8d-abca-4dd530eabf4c"], "text": "— Я звонил. — Олжас говорит в пол. — Аке говорил, что сказать, я повторял. Про девочку тоже он сказал. Я бы сам не стал.", "grants": [], "fallback": true}, {"id": "R314", "on": "6d8d58c7-784b-5d25-9f9e-d6c55f6966ba", "requires": [], "text": "— Дома, значит. — Олжас кивает слишком быстро. — Ну да. Наверно, дома.", "grants": [], "fallback": true}, {"id": "R315", "on": "6d8d58c7-784b-5d25-9f9e-d6c55f6966ba", "requires": ["3ad29f0f-a1d4-5f8d-abca-4dd530eabf4c"], "text": "— Не дома он был. — Олжас поднимает голову. — У немцев. С ним. Свечка… Там лампа была. Керосиновая.", "grants": [], "fallback": true}, {"id": "R316", "on": "7188cb7d-2261-5a9c-8f78-e603caa6b31a", "requires": [], "text": "Олжас долго молчит.\n— Мен не знаю, кому он дом показывал.", "grants": [], "fallback": true}, {"id": "R317", "on": "7188cb7d-2261-5a9c-8f78-e603caa6b31a", "requires": ["3ad29f0f-a1d4-5f8d-abca-4dd530eabf4c"], "text": "— Какой покупатель. — Олжас качает головой. — Никого не было. Аке, я и он. В подвале.", "grants": [], "fallback": true}, {"id": "R319", "on": "009a36f7-b362-586d-8943-61cd46149c3c", "requires": [], "text": "— Это их дела. Взрослых. — Олжас смотрит в окно. — Мен не знаю.", "grants": [], "fallback": true}, {"id": "R323", "on": "b229ab87-5e5b-5f61-8a7b-18c17718e4cf", "requires": ["3ad29f0f-a1d4-5f8d-abca-4dd530eabf4c"], "text": "— Аке говорил: на базе человек есть, всё скажет. — Олжас пожимает плечами. — Кто — не говорил.", "grants": [], "fallback": true}]'::jsonb where id = 'ea6167fb-4eea-5e08-ae65-e5fce24e6a6c';  -- Олжас Бекенов
update characters set reaction_rules = (select coalesce(jsonb_agg(r), '[]'::jsonb) from jsonb_array_elements(coalesce(reaction_rules, '[]'::jsonb)) r where r->>'id' not in ('R310')) || '[{"id": "R310", "on": "42ea83ef-f3ad-504f-99e0-da4ecb9fe57d", "requires": [], "text": "Фархад качает головой.\n— Алия… Хорошая девочка была. Характер только. — Разводит руками. — В пятницу пустой, в воскресенье машина. Значит, приехал он, дорогой. Приехал, грелся. Света же не было.", "grants": [], "fallback": true}]'::jsonb where id = '5b4c1ece-ba00-50d6-9113-73e03e05ccd8';  -- Фархад Мамаджанов
commit;
select name, jsonb_array_length(reaction_rules) from characters where case_id = '029e23c3-01e0-5d19-a0e7-3e0c2446ebab' order by name;
